+.ars_make_density_evaluator <- function(density_expression, caller) {
+  expr <- density_expression
+  if (is.expression(expr)) {
+    if (length(expr) != 1L) {
+      stop("density expression must contain exactly one expression", call. = FALSE)
+    }
+    expr <- expr[[1L]]
+  }
+
+  # Resolve symbols and function literals now.  A call such as dnorm(x) is
+  # deliberately left unevaluated so that x can be supplied later.
+  if (is.symbol(expr) || (is.call(expr) && identical(expr[[1L]], as.name("function")))) {
+    value <- tryCatch(eval(expr, envir = caller), error = function(e) NULL)
+    if (is.function(value)) {
+      return(function(x) value(x))
+    }
+    if (is.expression(value) && length(value) == 1L) {
+      expr <- value[[1L]]
+    } else if (is.symbol(expr)) {
+      stop("density_function must evaluate to a function or a density expression", call. = FALSE)
+    }
+  }
+
+  if (!is.language(expr)) {
+    stop("density_function must be a function or an expression involving x", call. = FALSE)
+  }
+
+  function(x) {
+    evaluation_environment <- list2env(list(x = x), parent = caller)
+    tryCatch(
+      eval(expr, envir = evaluation_environment),
+      error = function(e) stop(sprintf("density expression failed: %s", conditionMessage(e)), call. = FALSE)
+    )
+  }
+}
+
+.ars_log_density <- function(evaluator, x) {
+  x <- as.numeric(x)
+  raw <- evaluator(x)
+  if (!is.numeric(raw) || is.complex(raw) || length(raw) != length(x)) {
+    stop("density_function must return a numeric vector with one value per x", call. = FALSE)
+  }
+  if (any(is.na(raw)) || any(is.nan(raw))) {
+    stop("density_function returned NA or NaN", call. = FALSE)
+  }
+  if (any(raw < 0)) {
+    stop("density_function returned a negative density", call. = FALSE)
+  }
+  if (any(is.infinite(raw) & raw > 0)) {
+    stop("density_function returned an infinite density", call. = FALSE)
+  }
+  result <- rep(-Inf, length(raw))
+  positive <- raw > 0
+  result[positive] <- log(raw[positive])
+  result
+}
+
+.ars_concavity_tolerance <- function(values) {
+  1e-6 * max(1, abs(values), na.rm = TRUE)
+}
+
+.ars_check_secant_concavity <- function(x, h, context = "density") {
+  if (length(x) < 3L) {
+    return(invisible(TRUE))
+  }
+  secants <- diff(h) / diff(x)
+  tolerance <- .ars_concavity_tolerance(secants)
+  if (any(diff(secants) > tolerance)) {
+    stop(sprintf("%s is not log-concave at the evaluated points", context), call. = FALSE)
+  }
+  invisible(TRUE)
+}
+
+.ars_numerical_slopes <- function(x, h, domain, evaluator) {
+  slopes <- numeric(length(x))
+  lower <- domain$lower
+  upper <- domain$upper
+
+  for (i in seq_along(x)) {
+    xi <- x[i]
+    step <- 1e-5 * max(1, abs(xi))
+    left_distance <- xi - lower
+    right_distance <- upper - xi
+    if (is.finite(left_distance)) {
+      step <- min(step, 0.2 * left_distance)
+    }
+    if (is.finite(right_distance)) {
+      step <- min(step, 0.2 * right_distance)
+    }
+    if (!is.finite(step) || step <= 0) {
+      stop("unable to estimate a log-density slope inside domain", call. = FALSE)
+    }
+
+    can_go_left <- !is.finite(lower) || xi - step > lower
+    can_go_right <- !is.finite(upper) || xi + step < upper
+    if (can_go_left && can_go_right) {
+      nearby <- .ars_log_density(evaluator, c(xi - step, xi + step))
+      if (any(!is.finite(nearby))) {
+        stop("density must be positive near every initial/adaptive knot", call. = FALSE)
+      }
+      slopes[i] <- (nearby[2L] - nearby[1L]) / (2 * step)
+    } else if (can_go_right) {
+      nearby <- .ars_log_density(evaluator, xi + step)
+      if (!is.finite(nearby)) {
+        stop("density must be positive near every initial/adaptive knot", call. = FALSE)
+      }
+      slopes[i] <- (nearby - h[i]) / step
+    } else if (can_go_left) {
+      nearby <- .ars_log_density(evaluator, xi - step)
+      if (!is.finite(nearby)) {
+        stop("density must be positive near every initial/adaptive knot", call. = FALSE)
+      }
+      slopes[i] <- (h[i] - nearby) / step
+    } else {
+      stop("unable to estimate a log-density slope inside domain", call. = FALSE)
+    }
+  }
+
+  if (any(!is.finite(slopes))) {
+    stop("could not calculate finite log-density slopes", call. = FALSE)
+  }
+  slopes
+}
+
+.ars_validate_knot_geometry <- function(x, h, slopes, context = "density") {
+  if (length(x) != length(h) || length(x) != length(slopes) ||
+      length(x) < 2L || any(!is.finite(x)) || any(diff(x) <= 0) ||
+      any(!is.finite(h)) || any(!is.finite(slopes))) {
+    stop(sprintf("invalid %s knot geometry", context), call. = FALSE)
+  }
+
+  if (length(x) >= 3L) {
+    secants <- diff(h) / diff(x)
+    tolerance <- .ars_concavity_tolerance(c(secants, slopes))
+    if (any(diff(secants) > tolerance)) {
+      stop(sprintf("non-log-concave density detected during %s", context), call. = FALSE)
+    }
+  }
+
+  if (length(slopes) >= 2L) {
+    slope_tolerance <- .ars_concavity_tolerance(slopes)
+    if (any(diff(slopes) > slope_tolerance)) {
+      stop(sprintf("non-log-concave density detected from %s slopes", context), call. = FALSE)
+    }
+  }
+  invisible(TRUE)
+}
+
+.ars_grid <- function(domain, attempt) {
+  lower <- domain$lower
+  upper <- domain$upper
+  if (is.finite(lower) && is.finite(upper)) {
+    probabilities <- seq(0.01, 0.99, length.out = 33L)
+    return(lower + probabilities * (upper - lower))
+  }
+
+  if (is.finite(lower) && is.infinite(upper)) {
+    scale <- max(1, 0.01 * abs(lower))
+    maximum_distance <- 8 * scale * 2^(attempt - 1L)
+    distances <- exp(seq(log(scale * 1e-3), log(maximum_distance), length.out = 33L))
+    return(lower + distances)
+  }
+
+  if (is.infinite(lower) && is.finite(upper)) {
+    scale <- max(1, 0.01 * abs(upper))
+    maximum_distance <- 8 * scale * 2^(attempt - 1L)
+    distances <- exp(seq(log(scale * 1e-3), log(maximum_distance), length.out = 33L))
+    return(upper - rev(distances))
+  }
+
+  maximum <- 8 * 2^(attempt - 1L)
+  seq(-maximum, maximum, length.out = 33L)
+}
+
+.ars_initial_state <- function(domain, evaluator) {
+  for (attempt in seq_len(12L)) {
+    grid_x <- .ars_grid(domain, attempt)
+    grid_h <- .ars_log_density(evaluator, grid_x)
+    valid <- is.finite(grid_h)
+    if (!any(valid)) {
+      stop("density is zero or invalid across the search domain", call. = FALSE)
+    }
+
+    # Floating-point underflow can create -Inf far out in a tail.  Use the
+    # contiguous positive section around the largest grid value for numerical
+    # initialization, while treating a second positive section as a violation
+    # of the single-interval support expected by ARS.
+    mode_index <- which.max(grid_h)
+    left_valid <- mode_index
+    while (left_valid > 1L && valid[left_valid - 1L]) {
+      left_valid <- left_valid - 1L
+    }
+    right_valid <- mode_index
+    while (right_valid < length(grid_h) && valid[right_valid + 1L]) {
+      right_valid <- right_valid + 1L
+    }
+    if (any(valid[seq_len(length(valid)) < left_valid]) ||
+        any(valid[seq_len(length(valid)) > right_valid])) {
+      stop("density appears to have separated positive regions; ARS requires one interval of support", call. = FALSE)
+    }
+    if (right_valid - left_valid + 1L >= 3L) {
+      .ars_check_secant_concavity(
+        grid_x[left_valid:right_valid], grid_h[left_valid:right_valid],
+        context = "density"
+      )
+    }
+
+    needs_expansion <- FALSE
+    if (is.infinite(domain$lower) && mode_index - left_valid <= 1L) {
+      needs_expansion <- TRUE
+    }
+    if (is.infinite(domain$upper) && right_valid - mode_index <= 1L) {
+      needs_expansion <- TRUE
+    }
+    if (needs_expansion && attempt < 12L) {
+      next
+    }
+
+    selected <- unique(round(seq(left_valid, right_valid, length.out = 3L)))
+    selected <- selected[selected >= left_valid & selected <= right_valid]
+    if (length(selected) < 3L) {
+      selected <- c(left_valid, floor((left_valid + right_valid) / 2), right_valid)
+      selected <- unique(selected)
+    }
+    knot_x <- grid_x[selected]
+    knot_h <- grid_h[selected]
+    slopes <- .ars_numerical_slopes(knot_x, knot_h, domain, evaluator)
+    .ars_validate_knot_geometry(knot_x, knot_h, slopes, context = "initialization")
+
+    tail_tolerance <- 1e-7 * max(1, abs(slopes))
+    if (is.infinite(domain$lower) && slopes[1L] <= tail_tolerance[1L]) {
+      if (attempt < 12L) next
+      stop("the left tail tangent is not integrable; check the domain and log-concavity", call. = FALSE)
+    }
+    if (is.infinite(domain$upper) && slopes[length(slopes)] >= -tail_tolerance[length(slopes)]) {
+      if (attempt < 12L) next
+      stop("the right tail tangent is not integrable; check the domain and log-concavity", call. = FALSE)
+    }
+
+    return(list(x = knot_x, h = knot_h, slopes = slopes))
+  }
+  stop("could not find a valid log-concave initialization", call. = FALSE)
+}
+
+.ars_log_one_minus_exp_neg <- function(value) {
+  if (value < 1e-5) {
+    log(-expm1(-value))
+  } else {
+    log1p(-exp(-value))
+  }
+}
+
+.ars_log_linear_integral <- function(slope, intercept, lower, upper) {
+  if (is.infinite(lower) && is.infinite(upper)) {
+    return(-Inf)
+  }
+  if (is.infinite(lower)) {
+    if (slope <= 0) return(-Inf)
+    return(intercept + slope * upper - log(slope))
+  }
+  if (is.infinite(upper)) {
+    if (slope >= 0) return(-Inf)
+    return(intercept + slope * lower - log(-slope))
+  }
+
+  width <- upper - lower
+  if (!is.finite(width) || width <= 0) return(-Inf)
+  if (slope == 0) return(intercept + log(width))
+
+  if (slope > 0) {
+    delta <- slope * width
+    if (delta > 50) {
+      intercept + slope * upper + .ars_log_one_minus_exp_neg(delta) - log(slope)
+    } else {
+      intercept + slope * lower + log(expm1(delta)) - log(slope)
+    }
+  } else {
+    delta <- -slope * width
+    intercept + slope * lower + .ars_log_one_minus_exp_neg(delta) - log(-slope)
+  }
+}
+
+.ars_build_hull <- function(x, h, slopes, domain) {
+  .ars_validate_knot_geometry(x, h, slopes, context = "hull")
+  x <- as.numeric(x)
+  h <- as.numeric(h)
+  slopes <- as.numeric(slopes)
+
+  # Equal slopes describe a linear section of the log density.  Such knots do
+  # not define a finite intersection, so redundant knots are removed.
+  repeat {
+    if (length(slopes) < 2L) break
+    slope_tolerance <- .ars_concavity_tolerance(slopes)
+    equal_pair <- which(abs(diff(slopes)) <= slope_tolerance)[1L]
+    if (is.na(equal_pair)) break
+    intercepts <- h - slopes * x
+    intercept_tolerance <- 1e-5 * max(1, abs(intercepts))
+    if (abs(intercepts[equal_pair] - intercepts[equal_pair + 1L]) > intercept_tolerance) {
+      stop("equal adjacent log-density slopes have inconsistent tangent lines", call. = FALSE)
+    }
+    remove <- equal_pair + 1L
+    x <- x[-remove]
+    h <- h[-remove]
+    slopes <- slopes[-remove]
+  }
+
+  intercept_margin <- 1e-8 * max(1, abs(h))
+  intercepts <- h - slopes * x + intercept_margin
+  k <- length(x)
+  z <- c(domain$lower, rep(NA_real_, max(0L, k - 1L)), domain$upper)
+  if (k >= 2L) {
+    for (i in seq_len(k - 1L)) {
+      denominator <- slopes[i] - slopes[i + 1L]
+      if (!is.finite(denominator) || denominator <= 0) {
+        stop("tangent slopes do not form a valid decreasing hull", call. = FALSE)
+      }
+      z[i + 1L] <- (h[i + 1L] - h[i] + slopes[i] * x[i] - slopes[i + 1L] * x[i + 1L]) /
+        denominator
+    }
+  }
+
+  boundary_tolerance <- 1e-10 * max(1, abs(x), na.rm = TRUE)
+  if (length(z) >= 3L && any(diff(z) <= boundary_tolerance)) {
+    stop("tangent intersections are not ordered; density may not be log-concave", call. = FALSE)
+  }
+  if (is.finite(domain$lower) && z[1L] < domain$lower) z[1L] <- domain$lower
+  if (is.finite(domain$upper) && z[length(z)] > domain$upper) z[length(z)] <- domain$upper
+
+  log_integrals <- numeric(k)
+  for (i in seq_len(k)) {
+    log_integrals[i] <- .ars_log_linear_integral(
+      slopes[i], intercepts[i], z[i], z[i + 1L]
+    )
+  }
+  if (any(!is.finite(log_integrals))) {
+    stop("the tangent envelope is not integrable; check log-concavity and domain", call. = FALSE)
+  }
+
+  list(
+    x = x,
+    h = h,
+    slopes = slopes,
+    intercepts = intercepts,
+    z = z,
+    log_integrals = log_integrals
+  )
+}
+
+.ars_sample_hull <- function(hull) {
+  maximum <- max(hull$log_integrals)
+  probabilities <- exp(hull$log_integrals - maximum)
+  interval <- sample.int(length(probabilities), size = 1L, prob = probabilities)
+  lower <- hull$z[interval]
+  upper <- hull$z[interval + 1L]
+  slope <- hull$slopes[interval]
+  intercept <- hull$intercepts[interval]
+  u <- min(max(runif(1L), .Machine$double.eps), 1 - .Machine$double.eps)
+
+  if (is.infinite(lower)) {
+    proposal <- upper + log(u) / slope
+  } else if (is.infinite(upper)) {
+    proposal <- lower + log(u) / slope
+  } else {
+    width <- upper - lower
+    scaled_slope <- slope * width
+    if (abs(scaled_slope) < 1e-8) {
+      proposal <- lower + u * width
+    } else if (slope > 0) {
+      if (scaled_slope > 50) {
+        proposal <- upper + log(u + (1 - u) * exp(-scaled_slope)) / slope
+      } else {
+        proposal <- lower + log1p(u * expm1(scaled_slope)) / slope
+      }
+    } else {
+      if (-scaled_slope > 50) {
+        proposal <- lower + log((1 - u) + u * exp(scaled_slope)) / slope
+      } else {
+        proposal <- lower + log1p(u * expm1(scaled_slope)) / slope
+      }
+    }
+  }
+  if (!is.finite(proposal)) {
+    stop("failed to draw from the tangent envelope", call. = FALSE)
+  }
+  proposal
+}
+
+.ars_hull_value <- function(hull, x) {
+  interval <- findInterval(x, hull$z, rightmost.closed = TRUE)
+  interval <- min(max(interval, 1L), length(hull$slopes))
+  hull$intercepts[interval] + hull$slopes[interval] * x
+}
+
+.ars_add_knot <- function(state, x, h, slope) {
+  duplicate_tolerance <- 1e-10 * max(1, abs(x), abs(state$x))
+  if (any(abs(state$x - x) <= duplicate_tolerance)) {
+    return(state)
+  }
+  position <- findInterval(x, state$x) + 1L
+  state$x <- append(state$x, x, after = position - 1L)
+  state$h <- append(state$h, h, after = position - 1L)
+  state$slopes <- append(state$slopes, slope, after = position - 1L)
+  .ars_validate_knot_geometry(state$x, state$h, state$slopes, context = "adaptive sampling")
+  state
+}
+
+#' Adaptive rejection sampler for a one-dimensional log-concave density.
+#'
+#' density_function may be a vectorized function or an expression such as
+#' dnorm(x).  domain is a two-element interval and n is the number of draws.
+ars <- function(density_function, domain, n = sample_count) {
+  if (missing(n)) {
+    n <- 1L
+  }
+  n <- .ars_validate_sample_count(n)
+  domain <- .ars_validate_domain(domain)
+  density_expression <- substitute(density_function)
+  evaluator <- .ars_make_density_evaluator(density_expression, parent.frame())
+  state <- .ars_initial_state(domain, evaluator)
+
+  if (n == 0L) {
+    return(numeric(0L))
+  }
+
+  samples <- numeric(n)
+  accepted <- 0L
+  attempts <- 0L
+  maximum_attempts <- max(10000L, 200L * n)
+
+  while (accepted < n) {
+    attempts <- attempts + 1L
+    if (attempts > maximum_attempts) {
+      stop("sampling exceeded the maximum number of attempts; check the density and domain", call. = FALSE)
+    }
+
+    hull <- .ars_build_hull(state$x, state$h, state$slopes, domain)
+    proposal <- .ars_sample_hull(hull)
+    log_target <- .ars_log_density(evaluator, proposal)[1L]
+    log_envelope <- .ars_hull_value(hull, proposal)
+
+    if (is.finite(log_target)) {
+      envelope_error <- log_target - log_envelope
+      if (envelope_error > 1e-6 * max(1, abs(log_target), abs(log_envelope))) {
+        stop("tangent envelope fell below the density; density may not be log-concave", call. = FALSE)
+      }
+      if (log(runif(1L)) <= min(0, envelope_error)) {
+        accepted <- accepted + 1L
+        samples[accepted] <- proposal
+      }
+
+      proposal_slope <- .ars_numerical_slopes(proposal, log_target, domain, evaluator)[1L]
+      state <- .ars_add_knot(state, proposal, log_target, proposal_slope)
+      if (length(state$x) > 2000L) {
+        stop("adaptive envelope exceeded 2000 knots; check density log-concavity", call. = FALSE)
+      }
+    }
+  }
+  samples
+}
+
+.ars_test_result <- function(name, passed, sample = NULL, expected = "") {
+  status <- if (isTRUE(passed)) "PASS" else "FAIL"
+  if (is.null(sample)) {
+    cat(sprintf("%s: %s | mean=NA | sd=NA%s\n", name, status, expected))
+  } else {
+    cat(sprintf(
+      "%s: %s | mean=%.6f | sd=%.6f%s\n",
+      name, status, mean(sample), stats::sd(sample), expected
+    ))
+  }
+  isTRUE(passed)
+}
